
  create table "public"."sales_documents" (
    "id" bigint generated by default as identity not null,
    "sales_id" bigint not null,
    "type" text not null,
    "file" jsonb not null,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."sales_documents" enable row level security;

alter table "public"."choices" add column "requires_renewal" boolean not null default false;

CREATE UNIQUE INDEX sales_documents_pkey ON public.sales_documents USING btree (id);

CREATE UNIQUE INDEX uq__sales_documents__sales_id_type ON public.sales_documents USING btree (sales_id, type);

alter table "public"."sales_documents" add constraint "sales_documents_pkey" PRIMARY KEY using index "sales_documents_pkey";

alter table "public"."sales_documents" add constraint "sales_documents_sales_id_fkey" FOREIGN KEY (sales_id) REFERENCES public.sales(id) ON DELETE CASCADE not valid;

alter table "public"."sales_documents" validate constraint "sales_documents_sales_id_fkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.is_own_sale(sale_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return exists (
    select 1 from public.sales where id = sale_id and user_id = auth.uid()
  );
end;
$function$
;

